import { type ChangeEvent, type Dispatch, type FormEvent, type SetStateAction, useEffect, useMemo, useRef, useState } from "react";
import type { AppState, CashDraft, CashSession, Currency, LeaderboardConfig, LeaderboardPool, Mode, Reward, Room, StoredVault, Tab, TournamentDraft, UniversalDraft, Vault } from "./types";
import { bigBlind, cashDraft, decryptState, demoState, deriveKey, emptyState, encryptState, loadVaults, money, num, percent, roomCurrency, roomName, saveVaults, signed, today, tournamentDraft, uid, universalDraft } from "./data";
