  const total=draft.rows.reduce((sum,row)=>sum+rowResult(row),0),cash=draft.rows.reduce((sum,row)=>sum+Number(row.cashResult||0),0),mtt=draft.rows.reduce((sum,row)=>sum+Number(row.mttResult||0),0);
