function Settings({ state, setState, demo, lock, vault, importVault }: { state: AppState; setState: Setter; demo: boolean; lock:()=>void; vault?: Vault; importVault:(vault:Vault)=>void }) {
  const download=()=>{if(!vault)return;const url=URL.createObjectURL(new Blob([JSON.stringify(vault)],{type:"application/json"})),a=document.createElement("a");a.href=url;a.download=`grindtrack-backup-${today}.json`;a.click();URL.revokeObjectURL(url);};
  const upload=async(e:ChangeEvent<HTMLInputElement>)=>{const file=e.target.files?.[0];if(!file)return;try{const raw=await file.text(),imported=JSON.parse(raw) as Vault;if(!imported.salt||!imported.iv||!imported.cipher)throw new Error();importVault(imported);alert("Backup imported as a separate account. Select it and unlock with its PIN.");}catch{alert("Not a valid GrindTrack backup.")}};
  const addRoom=(event:FormEvent<HTMLFormElement>)=>{event.preventDefault();const form=new FormData(event.currentTarget),balance=num(form.get("balance")),room:Room={id:uid(),name:String(form.get("name")),kind:String(form.get("kind")) as Room["kind"],mode:String(form.get("mode")) as Room["mode"],currency:String(form.get("currency")) as Currency,startingBalance:balance,currentBalance:balance};setState((current)=>current&&withAddedRoom(current,room));event.currentTarget.reset()};
  const deleteRoom=(roomId:string)=>{const room=state.rooms.find((item)=>item.id===roomId);if(!room||!window.confirm(`Delete ${room.name}? Its saved sessions, daily results and rakeback entries will also be deleted.`))return;setState((current)=>{if(!current)return current;const rooms=current.rooms.filter((item)=>item.id!==roomId),tournamentRoom=rooms.find((item)=>item.kind==="room"&&(item.mode==="tournament"||item.mode==="both"))?.id||"",cashRoom=rooms.find((item)=>item.kind==="room"&&(item.mode==="cash"||item.mode==="both"))?.id||"",universalRoom=rooms.find((item)=>item.kind==="room")?.id||"",tournamentRows=current.drafts.tournament.rows.filter((row)=>row.roomId!==roomId),universalRows=current.drafts.universal.rows.filter((row)=>row.roomId!==roomId);return {...current,rooms,tournamentDays:current.tournamentDays.map((day)=>({...day,entries:day.entries.filter((entry)=>entry.roomId!==roomId)})).filter((day)=>day.entries.length),cashSessions:current.cashSessions.filter((session)=>session.roomId!==roomId),universalDays:current.universalDays.map((day)=>({...day,entries:day.entries.filter((entry)=>entry.roomId!==roomId)})).filter((day)=>day.entries.length),rewards:current.rewards.filter((reward)=>reward.roomId!==roomId),leaderboardConfigs:current.leaderboardConfigs.map((config)=>config.roomId===roomId?{...config,roomId:""}:config),drafts:{tournament:tournamentRows.length?{...current.drafts.tournament,rows:tournamentRows}:tournamentDraft(tournamentRoom),cash:current.drafts.cash.roomId===roomId?cashDraft(cashRoom):current.drafts.cash,universal:universalRows.length?{...current.drafts.universal,rows:universalRows}:universalDraft(universalRoom)}}})};
  const deleteAll=()=>{if(!state.rooms.length||!window.confirm("Delete every room and wallet? This also deletes all tracked sessions, results and rakeback history. This cannot be undone."))return;setState((current)=>current&&({...current,rooms:[],tournamentDays:[],cashSessions:[],universalDays:[],rewards:[],leaderboardConfigs:current.leaderboardConfigs.map((config)=>({...config,roomId:""})),drafts:{tournament:tournamentDraft(),cash:cashDraft(),universal:universalDraft()}}))};
  return <div className="stack"><section className="panel setting"><div><p className="eyebrow">PROFILE</p><h2>Your private journal</h2><p>Nothing is uploaded to GitHub or shared with other players.</p></div><label>Player name<input value={state.profileName} onChange={(e)=>setState((s)=>s&&({...s,profileName:e.target.value}))}/></label></section><section className="panel setting"><div><p className="eyebrow">BACKUP</p><h2>Protect your history</h2><p>Export an encrypted backup regularly. Imported backups become separate accounts.</p></div><aside><button className="secondary" disabled={demo||!vault} onClick={download}>Export encrypted backup</button><label className="secondary file">Import backup<input type="file" accept="application/json" disabled={demo} onChange={upload}/></label></aside></section><section className="panel"><header><div><p className="eyebrow">ROOMS</p><h2>Manage rooms</h2></div><button className="danger-button" disabled={!state.rooms.length} onClick={deleteAll}>Delete all rooms</button></header>{state.rooms.length?<div className="manage">{state.rooms.map((room)=><div key={room.id}><i>{room.name.slice(0,2).toUpperCase()}</i><b>{room.name}</b><small>{room.kind} · {room.mode} · {room.currency}</small><button aria-label={`Delete ${room.name}`} className="remove" onClick={()=>deleteRoom(room.id)}>×</button></div>)}</div>:<Empty>No rooms yet. Add exactly what you need below.</Empty>}<form className="inline settings-add" onSubmit={addRoom}><label>Name<input name="name" required placeholder="e.g. Nike"/></label><label>Type<select name="kind"><option value="room">Poker room</option><option value="wallet">Wallet</option></select></label><label>Used for<select name="mode" defaultValue="both"><option value="tournament">MTT only</option><option value="cash">Cash only</option><option value="both">All modes</option></select></label><label>Currency<select name="currency"><option>USD</option><option>EUR</option></select></label><label>Starting balance<input name="balance" type="number" step=".01" placeholder="0"/></label><button className="primary">Add room</button></form></section><section className="panel setting"><div><p className="eyebrow">PRIVACY</p><h2>{demo?"Leave demo":"Log out of this vault"}</h2><p>{demo?"Demo changes are temporary.":"Return to the account selector. Your encrypted data stays on this device."}</p></div><button className="secondary" onClick={lock}>{demo?"Exit demo":"Log out"}</button></section></div>;
}

export default function App() {
  const [state,setState]=useState<AppState|null>(null),[key,setKey]=useState<CryptoKey|null>(null),[salt,setSalt]=useState<Uint8Array|null>(null),[demo,setDemo]=useState(false),[mode,setMode]=useState<Mode>("universal"),[tab,setTab]=useState<Tab>("dashboard"),[saved,setSaved]=useState(true),[vaults,setVaults]=useState<StoredVault[]>(()=>loadVaults()),[activeVaultId,setActiveVaultId]=useState<string|null>(null);
  useEffect(()=>{if(!state||!key||!salt||demo||!activeVaultId)return;setSaved(false);const timer=setTimeout(async()=>{const encrypted=await encryptState(state,key,salt);setVaults((current)=>{const next=current.map((stored)=>stored.id===activeVaultId?{...stored,name:state.profileName,vault:encrypted}:stored);saveVaults(next);return next});setSaved(true)},300);return()=>clearTimeout(timer)},[state,key,salt,demo,activeVaultId]);
  if(!state)return <Gate vaults={vaults} setVaults={setVaults} enter={(next,nextKey,nextSalt,isDemo=false,vaultId)=>{setState(next);setKey(nextKey||null);setSalt(nextSalt||null);setDemo(isDemo);setActiveVaultId(vaultId||null)}}/>;
  const nav:{id:Tab;label:string;sub:string}[]=[{id:"dashboard",label:"Dashboard",sub:"Overview"},{id:"balances",label:"Balances",sub:"Bankroll"},{id:"daily",label:mode==="tournament"?"Daily grind":mode==="cash"?"Sessions":"Daily mix",sub:"Add result"},...(mode==="cash"?[{id:"leaderboard" as Tab,label:"LB Analysis",sub:"Leaderboards"}]:[]),{id:"rakeback",label:"Rakeback",sub:"Rewards"},{id:"settings",label:"Settings",sub:"Data"}],mobileNav=mode==="cash"?nav.filter((item)=>item.id!=="settings"):nav.slice(0,4);
  const leave=()=>{setState(null);setKey(null);setSalt(null);setDemo(false);setActiveVaultId(null);setMode("universal");setTab("dashboard")};
  const lock=async()=>{if(state&&key&&salt&&!demo&&activeVaultId){const encrypted=await encryptState(state,key,salt),next=vaults.map((stored)=>stored.id===activeVaultId?{...stored,name:state.profileName,vault:encrypted}:stored);saveVaults(next);setVaults(next)}leave()};
  const importVault=(vault:Vault)=>{const next=[...vaults,{id:uid(),name:`Imported account ${vaults.length+1}`,vault}];saveVaults(next);setVaults(next);leave()};
  const activeVault=vaults.find((stored)=>stored.id===activeVaultId)?.vault;
  const changeMode=(next:Mode)=>{setMode(next);if(tab==="leaderboard"&&next!=="cash")setTab("dashboard")};
  return <div className="shell"><aside className="side"><div className="brand"><div className="logo small">GT</div><span><b>GrindTrack</b><small>PRIVATE JOURNAL</small></span></div><div className="mode"><button className={mode==="universal"?"active":""} onClick={()=>changeMode("universal")}>ALL</button><button className={mode==="cash"?"active":""} onClick={()=>changeMode("cash")}>CASH</button><button className={mode==="tournament"?"active":""} onClick={()=>changeMode("tournament")}>MTT</button></div><nav>{nav.map((n)=><button key={n.id} className={tab===n.id?"active":""} onClick={()=>setTab(n.id)}><i/><span>{n.label}<small>{n.sub}</small></span></button>)}</nav><footer><i className={saved?"":"saving"}/>{demo?"Demo · not saved":saved?"Encrypted · saved":"Encrypting…"}</footer></aside><main className="content"><header className="top"><div><p className="eyebrow">{mode==="tournament"?"TOURNAMENT GRIND":mode==="cash"?"CASH GRIND":"ALL GRIND"}</p><h1>{nav.find((n)=>n.id===tab)?.label}</h1></div><div className="profile"><span><b>{state.profileName}</b><small>{demo?"Demo vault":"Private vault"}</small></span><i>{state.profileName.slice(0,2).toUpperCase()}</i><button className="logout" onClick={lock}>Log out</button></div></header>{tab==="dashboard"&&<Dashboard state={state} mode={mode}/>} {tab==="balances"&&<Balances state={state} setState={setState} mode={mode}/>} {tab==="daily"&&(mode==="tournament"?<TournamentDaily state={state} setState={setState}/>:mode==="cash"?<CashDaily state={state} setState={setState}/>:<UniversalDaily state={state} setState={setState}/>)} {tab==="leaderboard"&&mode==="cash"&&<LeaderboardAnalysis state={state} setState={setState}/>} {tab==="rakeback"&&<Rakeback state={state} setState={setState} mode={mode}/>} {tab==="settings"&&<Settings state={state} setState={setState} demo={demo} lock={lock} vault={activeVault} importVault={importVault}/>}</main><nav className={`mobile ${mobileNav.length===5?"five":""}`}>{mobileNav.map((n)=><button key={n.id} className={tab===n.id?"active":""} onClick={()=>setTab(n.id)}><i/>{n.label.replace("Daily grind","Daily").replace("Daily mix","Daily").replace("LB Analysis","LB")}</button>)}</nav></div>;
}
